// companion/internal/shell/chrome.go
// The window chrome's numbers, kept apart from the Win32 calls that use
// them so a test on any platform can check them. The colours are the design
// tokens through internal/brand (generated by design/tokens/build.mjs from
// design/tokens/tokens.json): the title bar is the site's nav-bar teal, the
// colour the window's painted band opens with, so the caption reads as one
// band with it; the page behind the webview is the brown ground, so nothing
// flashes white while it starts.
package shell

import (
	"fmt"
	"image/color"

	"github.com/jhunthrop/foreversixty/companion/internal/brand"
)

// rect is a screen rectangle in pixels, as Win32 has it.
type rect struct{ Left, Top, Right, Bottom int32 }

// colorRef is a Win32 COLORREF, 0x00BBGGRR.
func colorRef(c color.NRGBA) uint32 {
	return uint32(c.B)<<16 | uint32(c.G)<<8 | uint32(c.R)
}

// The title bar's ground, ink and edge, and the page behind the webview.
var (
	captionColor = colorRef(brand.ColorForeverNavBar)
	captionText  = colorRef(brand.ColorForeverCream)
	borderColor  = colorRef(brand.ColorForeverFoot)
	pageColor    = colorRef(brand.ColorForeverGround)
)

// pageARGB is the page colour as the webview's own default background
// wants it, 0xAARRGGBB as hex digits (WEBVIEW2_DEFAULT_BACKGROUND_COLOR).
var pageARGB = argb(brand.ColorForeverGround)

func argb(c color.NRGBA) string { return fmt.Sprintf("%02X%02X%02X%02X", c.A, c.R, c.G, c.B) }

// MinWidth and MinHeight are the smallest the window may be dragged to;
// the page is laid out for 560 wide and up.
const (
	MinWidth  = 560
	MinHeight = 480
)

// centred is the top-left corner that puts a w by h window in the middle
// of the work area, the screen less the taskbar. A work area smaller than
// the window pins the window to its top-left corner rather than off it.
func centred(work rect, w, h int32) (x, y int32) {
	x = work.Left + (work.Right-work.Left-w)/2
	y = work.Top + (work.Bottom-work.Top-h)/2
	if x < work.Left {
		x = work.Left
	}
	if y < work.Top {
		y = work.Top
	}
	return x, y
}
